//! Text rendering from the glyph atlas generated by build.rs.
//!
//! Pen positions are fixed point (1/256 px). Glyphs were pre-rendered at
//! `phases` sub-pixel offsets, so the fractional part of the pen picks the
//! closest phase and spacing stays exact instead of snapping every glyph.

use crate::assets::STRIKES;
use crate::gfx::{Canvas, Color, blend};

pub struct Glyph {
    pub ch: u32,
    pub phase: u8,
    pub w: u16,
    pub h: u16,
    pub left: i16,
    pub top: i16,
    pub advance: i32,
    pub offset: u32,
}

pub struct Strike {
    pub style: &'static str,
    pub size: u32,
    pub scale: u32,
    pub phases: u8,
    pub ascent: i32,
    pub descent: i32,
    pub glyphs: &'static [Glyph],
    pub kerning: &'static [(u32, u32, i32)],
    pub bitmap: &'static [u8],
}

#[derive(Clone, Copy, PartialEq, Eq)]
pub enum Style {
    Small,
    Body,
    BodyMedium,
    Title,
}

impl Style {
    fn key(self) -> (&'static str, u32) {
        match self {
            Style::Small => ("Regular", 13),
            Style::Body => ("Regular", 16),
            Style::BodyMedium => ("Medium", 16),
            Style::Title => ("SemiBold", 40),
        }
    }
}

pub fn strike(style: Style, scale: u32) -> &'static Strike {
    let (name, size) = style.key();
    STRIKES
        .iter()
        .find(|s| s.style == name && s.size == size && s.scale == scale)
        .or_else(|| STRIKES.iter().find(|s| s.style == name && s.size == size))
        .expect("strike")
}

impl Strike {
    fn glyph(&self, ch: u32, phase: u8) -> Option<&Glyph> {
        self.glyphs
            .binary_search_by(|g| (g.ch, g.phase).cmp(&(ch, phase)))
            .ok()
            .map(|i| &self.glyphs[i])
    }

    fn lookup(&self, ch: char, phase: u8) -> &Glyph {
        self.glyph(ch as u32, phase)
            .or_else(|| self.glyph('?' as u32, phase))
            .expect("fallback glyph")
    }

    fn kern(&self, a: char, b: char) -> i32 {
        self.kerning
            .binary_search_by(|&(x, y, _)| (x, y).cmp(&(a as u32, b as u32)))
            .map(|i| self.kerning[i].2)
            .unwrap_or(0)
    }

    /// Width of `text` in 1/256 px.
    pub fn measure(&self, text: &str) -> i32 {
        let mut w = 0;
        let mut prev: Option<char> = None;
        for ch in text.chars() {
            if let Some(p) = prev {
                w += self.kern(p, ch);
            }
            w += self.lookup(ch, 0).advance;
            prev = Some(ch);
        }
        w
    }

    /// Width of `text` in whole pixels (rounded up).
    pub fn width(&self, text: &str) -> i32 {
        (self.measure(text) + 255) >> 8
    }

    /// Draw `text` with the pen starting at `x` (1/256 px) on baseline `y`.
    /// `alpha` (0..=255) scales coverage. Returns the pen position after the text.
    pub fn draw(&self, canvas: &mut Canvas, x: i32, y: i32, text: &str, color: Color, alpha: i32) -> i32 {
        let lin = color.linear();
        let phases = self.phases.max(1) as i32;
        let mut pen = x;
        let mut prev: Option<char> = None;
        for ch in text.chars() {
            if let Some(p) = prev {
                pen += self.kern(p, ch);
            }
            prev = Some(ch);
            let whole = pen >> 8;
            let frac = pen & 255;
            let mut phase = (frac * phases + 128) >> 8;
            let mut gx = whole;
            if phase == phases {
                phase = 0;
                gx += 1;
            }
            let g = self.lookup(ch, phase as u8);
            let x0 = gx + g.left as i32;
            let y0 = y - g.top as i32;
            let (w, h) = (g.w as i32, g.h as i32);
            for row in 0..h {
                let py = y0 + row;
                if py < 0 || py >= canvas.h {
                    continue;
                }
                let src = g.offset as usize + (row * w) as usize;
                let dst = (py * canvas.w) as usize;
                for col in 0..w {
                    let px = x0 + col;
                    if px < 0 || px >= canvas.w {
                        continue;
                    }
                    let cov = self.bitmap[src + col as usize] as i32;
                    if cov != 0 {
                        let i = dst + px as usize;
                        canvas.px[i] = blend(canvas.px[i], lin, cov * alpha / 255);
                    }
                }
            }
            pen += g.advance;
        }
        pen
    }

    /// Draw text in whole-pixel coordinates; returns the end x in pixels.
    pub fn draw_px(&self, canvas: &mut Canvas, x: i32, y: i32, text: &str, color: Color, alpha: i32) -> i32 {
        (self.draw(canvas, x << 8, y, text, color, alpha) + 255) >> 8
    }
}
